insert into public.catalogo_instituciones(nombre) select distinct trim(institucion) from public.personas where nullif(trim(institucion),'') is not null on conflict(nombre) do nothing;
insert into public.catalogo_carreras(nombre) select distinct trim(carrera) from public.personas where nullif(trim(carrera),'') is not null on conflict(nombre) do nothing;
insert into public.catalogo_municipios_tlaxcala(nombre) select distinct trim(municipio) from public.personas where nullif(trim(municipio),'') is not null on conflict(nombre) do nothing;
insert into public.catalogo_empresas(nombre,sector) select empresa,max(sector_empresa) from public.vacantes where nullif(trim(empresa),'') is not null group by empresa on conflict(nombre) do update set sector=coalesce(excluded.sector,public.catalogo_empresas.sector);
